/* Example of overlapping elements with absolute positioning */
body {
    position: relative;
    height: 300px;
}

.box {
    position: absolute;
    width: 100px;
    height: 100px;
}

.box1 { top: 20px; left: 20px; }
.box2 { top: 40px; left: 40px; }
.box3 { top: 60px; left: 60px; }

/* Example: controlling stacking order with z-index */
.box1 { z-index: 1; }
.box2 { z-index: 2; }
.box3 { z-index: 3; }

/* Creating a stacking context with opacity */
.element {
    opacity: 0.8;
}

/* Example: transform creates a stacking context */
.element {
    transform: rotate(5deg);
}

/* Similar: creating a stacking context with isolation */
.container {
    isolation: isolate;
}

/* Example of nested element with z-index */
.parent {
  position: relative;
  z-index: 1;
}
.parent .nested {
  position: absolute;
  z-index: 999;
}

/* Example: Adding visual distinction */
.box {
    border: 3px solid black;
}

/* Creating stacking context with filter */
.element {
    filter: blur(0);
}
